create table bas.cdn_components (id bigint not null, kind varchar(32) not null, name varchar(255) not null, mount_name varchar(255) not null, remark varchar(255), spec jsonb not null);
create table bas.cfg_artifacts (id bigint not null, arch integer not null, artifact_id varchar(255) not null, classifier varchar(255), context_path varchar(255) not null, description varchar(255) not null, group_id varchar(255) not null, jsp_support boolean default false not null, latest_version varchar(255) not null, packaging varchar(255) not null, profile_id bigint, resolve_support boolean default false not null, title varchar(255) not null, websocket_support boolean default false not null);
create table bas.cfg_engines (id integer not null, jsp_support boolean default false not null, name varchar(255) not null, profile_id bigint, remark varchar(255), typ varchar(255) not null, version varchar(255) not null, websocket_support boolean default false not null);
create table bas.cfg_engines_jars (engine_id integer not null, value_ varchar(255) not null);
create table bas.cfg_engines_listeners (engine_id integer not null, value_ varchar(255) not null);
create table bas.cfg_farms (id bigint not null, engine_id integer not null, max_heap_size integer default 0 not null, name varchar(255) not null, profile_id bigint not null, proxy_options varchar(255), server_options varchar(255));
create table bas.cfg_farms_hosts (farm_id bigint not null, host_id bigint not null);
create table bas.cfg_hosts (id bigint not null, arch integer not null, cores integer default 0 not null, cpu varchar(200) not null, ip varchar(255) not null, memory integer default 0 not null, name varchar(255) not null, platform_id integer not null, platform_version varchar(255) not null, profile_id bigint not null, setline_listen_port integer, setline_admin_port integer);
create table bas.cfg_hosts_features (host_id bigint not null, platform_feature_id bigint not null);
create table bas.cfg_organizations (id integer not null, logo_url varchar(255) not null, name varchar(255) not null, short_title varchar(255) not null, title varchar(255) not null);
create table bas.cfg_platform_feature_scripts (id bigint not null, feature_id bigint not null, platform_id integer not null, scripts varchar(4000) not null);
create table bas.cfg_platform_features (id bigint not null, description varchar(255) not null, logo varchar(255) not null, name varchar(255) not null, version varchar(255) not null);
create table bas.cfg_platform_features_dependencies (from_feature_id bigint not null, platform_feature_id bigint not null);
create table bas.cfg_platforms (id integer not null, fonticon varchar(255) not null, major_version varchar(255) not null, name varchar(255) not null);
create table bas.cfg_profile_micdn (profile_id bigint not null, config jsonb not null);
create table bas.cfg_profile_micdn_components (id bigint not null, component_id bigint not null, profile_id bigint not null, sortno integer default 0 not null);
create table bas.cfg_profiles (id bigint not null, enable_https boolean default false not null, force_https boolean default true not null, hostname varchar(255), proxy_by_hostname boolean default false not null, http_port integer default 80 not null, https_port integer default 443 not null, ip varchar(255) not null, "key" varchar(255) not null, local_repo varchar(255) not null, maxconn integer default 30000 not null, name varchar(255) not null, org_id integer not null, proxy_engine varchar(255) not null, remote_repo varchar(255) not null, bas_version varchar(255) not null, ssl_ciphers varchar(255), ssl_protocols varchar(255), ssl_certificate text, ssl_certificate_key text, title varchar(255) not null);
create table bas.cfg_servers (id bigint not null, farm_id bigint not null, host_id bigint not null, http_port integer default 0 not null, max_heap_size integer default 0 not null, name varchar(255) not null, proxy_http_port integer, proxy_options varchar(255));
create table bas.cfg_webapps (id bigint not null, artifact_id bigint not null, context_path varchar(255) not null, libs varchar(255), profile_id bigint not null, unpack boolean default false not null, urls jsonb not null, version varchar(255) not null);
create table bas.cfg_webapps_targets (server_id bigint not null, webapp_id bigint not null);
create table bas.ems_app_groups (id integer not null, name varchar(255) not null, title varchar(255) not null);
create table bas.ems_apps (id integer not null, artifact_id varchar(255) not null, group_id integer not null, name varchar(255) not null, services varchar(255), title varchar(255) not null);
create table bas.ems_channels (id integer not null, app_id integer not null, base varchar(200) not null, channel_type varchar(20) not null, embed_mode varchar(20) not null, enabled boolean default false not null);
create table bas.ems_menus (id integer not null, app_id integer not null, en_name varchar(255) not null, enabled boolean default false not null, entry_id integer, fonticon varchar(255), indexno varchar(255) not null, name varchar(255) not null, params varchar(255), parent_id integer, remark varchar(255));
create table bas.ems_menus_resources (menu_id integer not null, resource_id integer not null);
create table bas.ems_resources (id integer not null, actions varchar(255), app_id integer not null, enabled boolean default false not null, name varchar(255) not null, remark varchar(255), "scope" integer not null, title varchar(255) not null);
